"""Static, localised product pages and evidence-backed developer research."""
from pathlib import Path
import html,json,re

ROOT=Path(__file__).resolve().parents[1]
LANGUAGES=['en','es','fr','de','pt','zh','ja','ko','hi','ar','vi','th']
LOCALES={code:json.loads((ROOT/'website/locales'/f'{code}.json').read_text(encoding='utf-8')) for code in LANGUAGES}
UI={code:dict(zip(['copy','copied','select'],words)) for code,words in {
 'en':['Copy','Copied','Select the code to copy'], 'es':['Copiar','Copiado','Selecciona el código para copiarlo'], 'fr':['Copier','Copié','Sélectionnez le code à copier'], 'de':['Kopieren','Kopiert','Code zum Kopieren auswählen'], 'pt':['Copiar','Copiado','Selecione o código para copiar'], 'zh':['复制','已复制','请选择代码进行复制'], 'ja':['コピー','コピーしました','コードを選択してコピーしてください'], 'ko':['복사','복사됨','복사할 코드를 선택하세요'], 'hi':['कॉपी करें','कॉपी हो गया','कॉपी करने के लिए कोड चुनें'], 'ar':['نسخ','تم النسخ','حدد الشفرة لنسخها'], 'vi':['Sao chép','Đã sao chép','Chọn mã để sao chép'], 'th':['คัดลอก','คัดลอกแล้ว','เลือกโค้ดเพื่อคัดลอก']}.items()}
REPOS=[('MMDetection / RTMDet-Tiny','open-mmlab/mmdetection','https://github.com/open-mmlab/mmdetection','repo_rtmdet'),('D-FINE-N','Peterande/D-FINE','https://github.com/Peterande/D-FINE','repo_dfine'),('RF-DETR-Nano','roboflow/rf-detr','https://github.com/roboflow/rf-detr','repo_rf'),('ONNX Runtime','microsoft/onnxruntime','https://github.com/microsoft/onnxruntime','repo_ort')]
COPY_COMMANDS={
 'core':'python -m pip install -e .\nbehaviorkit demo --output runs/demo',
 'cpu':'python -m pip install -e ".[vision,cpu]"\nbehaviorkit doctor --provider cpu',
 'cuda':'python -m pip install -e ".[vision,cuda]"\nbehaviorkit doctor --provider cuda'}
SKIP={'en': 'Skip to content', 'es': 'Ir al contenido', 'fr': 'Aller au contenu', 'de': 'Zum Inhalt', 'pt': 'Ir para o conteúdo', 'zh': '跳转到正文', 'ja': '本文へスキップ', 'ko': '본문으로 건너뛰기', 'hi': 'मुख्य सामग्री पर जाएँ', 'ar': 'انتقل إلى المحتوى', 'vi': 'Chuyển đến nội dung', 'th': 'ข้ามไปยังเนื้อหา'}
def esc(value):return html.escape(str(value),quote=True)
def clean(value):return value.replace('\u2014',': ')
def home_path(code):return '/' if code=='en' else f'/{code}/index.html'
def start_path(code):return '/start.html' if code=='en' else f'/{code}/start.html'
def language_select(code,kind):
 options=''.join(f'<option value="{start_path(other) if kind=="start" else home_path(other)}" {"selected" if code==other else ""}>{esc(LOCALES[other]["name"])}</option>' for other in LANGUAGES)
 return f'<label class="language-control"><span class="sr-only">{esc(LOCALES[code]["nav"]["language"])}</span><select id="language-select" aria-label="{esc(LOCALES[code]["nav"]["language"])}">{options}</select></label>'

def shell(title,body,active=None,*,code='en',kind='reference',pages=()):
 locale=LOCALES[code];nav=locale['nav'];words=UI[code];home=home_path(code);start=start_path(code)
 side=f'<aside class="docs-nav"><span class="nav-label">DEVELOPER GUIDE</span>'+''.join(f'<a class="{"active" if slug==active else ""}" href="/docs/{slug}.html">{esc(label)}</a>' for slug,label in pages)+'<div class="nav-bottom">v0.3.0 · Feasibility prototype<br>No cloud inference required</div></aside>' if active else ''
 navlinks=[(home,nav['overview']),('/demo.html',nav['demo']),(start,nav['docs']),('/research.html',nav['research']),('/sources.html',nav['sources'])]
 links=''.join(f'<a href="{href}">{esc(label)}</a>' for href,label in navlinks)
 alternatives=''.join(f'<link rel="alternate" hreflang="{other}" href="{start_path(other) if kind=="start" else home_path(other)}">' for other in LANGUAGES) if kind in {'home','start'} else ''
 main_class='docs-main' if active else 'home-main' if kind=='lab' else 'professional-main'
 result=f'''<!doctype html><html lang="{code if code!='zh' else 'zh-Hans'}" dir="{locale['dir']}" data-copy-label="{esc(words['copy'])}" data-copy-done="{esc(words['copied'])}" data-copy-error="{esc(words['select'])}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} · BehaviorKit</title><meta name="description" content="{esc(locale['home']['lead'])}">{alternatives}<link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/professional.css"></head><body><a class="skip-link" href="#main">{esc(SKIP[code])} ↓</a><header class="topbar professional-header"><a class="brand" href="{home}" dir="ltr"><span class="mark">b<span>k</span></span>BehaviorKit<span class="version">0.3</span></a><nav id="main-navigation" aria-label="{esc(nav['overview'])}">{links}<a class="button small" href="/downloads/behaviorkit-prototype-source.zip">{esc(nav['download'])} ↗</a></nav><div class="header-tools">{language_select(code,kind)}<button id="menu" aria-label="{esc(nav['menu'])}" aria-expanded="false" aria-controls="main-navigation">{esc(nav['menu'])}</button></div></header>{side}<main id="main" class="{main_class}">{body}</main><footer class="professional-footer"><div><a class="brand" href="{home}" dir="ltr">BehaviorKit<span class="version">0.3.0</span></a><p>{esc(nav['footer'])}</p></div><div class="footer-links"><a href="{start}">{esc(nav['docs'])}</a><a href="/research.html">{esc(nav['research'])}</a><a href="/sources.html">{esc(nav['sources'])}</a><a href="/docs/commercial-use.html">Apache-2.0</a></div><p class="translation-scope">{esc(nav['reference'])}</p></footer><script src="/assets/app.js" defer></script><script src="/assets/professional.js" defer></script></body></html>'''
 if locale['dir']=='rtl':result=result.replace(' →',' ←').replace(' ↗',' ↖')
 return clean(result)

def code_block(command,code='en',identifier=None):
 label=UI[code]['copy'];ident=f' id="{identifier}"' if identifier else ''
 return f'<div class="pro-code"><button type="button" data-copy="{esc(command)}" aria-label="{esc(label)}">{esc(label)}</button><pre dir="ltr" lang="en"{ident}><code>{esc(command)}</code></pre></div>'

def home_body(code):
 t=LOCALES[code]['home'];tr=lambda key:esc(t[key]);start=start_path(code)
 validation=json.loads((ROOT/'benchmarks/reliability-v03.json').read_text());lab=json.loads((ROOT/'examples/video-lab/results/report.json').read_text())
 tests=validation['test_suites'][0]['passed'];skipped=validation['test_suites'][0]['skipped']
 frame_data=json.loads((ROOT/'examples/video-lab/results/data/shelf/rtmdet-tiny/frames.json').read_text());frame=min(frame_data['frames'],key=lambda row:abs(row['timestamp']-3.2));d=frame['tracks'][0];x1,y1,x2,y2=d['box']
 hero=f'''<section class="pro-hero"><div class="pro-hero-copy"><p class="eyebrow">{tr('eyebrow')}</p><span class="release-badge">{tr('release')}</span><h1>{tr('title_a')}<br><span>{tr('title_b')}</span></h1><p class="pro-lead">{tr('lead')}</p><div class="pro-actions"><a class="button" href="{start}">{tr('start')} →</a><a class="pro-text-link" href="/demo.html">{tr('watch')} ↗</a></div>{code_block('python -m pip install -e .',code)}<p class="pro-note">{tr('install_note')}</p></div><div class="pro-snapshot"><div class="snapshot-top"><span>{tr('preview_label')}</span><b dir="ltr">RTMDet-Tiny / CUDA</b></div><a class="pro-scene" href="/demo.html" dir="ltr" aria-label="{tr('preview_open')}"><img src="/assets/home-frame.jpg" width="960" height="540" alt="{tr('preview_title')}" fetchpriority="high"><span class="snapshot-box" style="left:{x1*100:.3f}%;top:{y1*100:.3f}%;width:{(x2-x1)*100:.3f}%;height:{(y2-y1)*100:.3f}%"><b>#{esc(d['track_id'])} · {d['confidence']:.2f}</b></span><span class="snapshot-anchor" style="left:{(x1+x2)*50:.3f}%;top:{y2*100:.3f}%"></span><span class="snapshot-time">t = {frame['timestamp']:.1f} s</span><span class="snapshot-open">↗</span></a><div class="snapshot-values"><div><span>{tr('cap_count_title')}</span><strong dir="ltr">{frame['count']['count']}</strong></div><div><span>{tr('cap_dwell_title')}</span><strong dir="ltr">3.0 s</strong></div><div><span>person_dwell</span><strong>✓</strong></div></div><div class="snapshot-caption"><h2>{tr('preview_title')}</h2><p>{tr('preview_body')}</p><a href="/demo.html">{tr('preview_open')} →</a><small>{tr('preview_credit')}</small></div></div></section>'''
 proof=f'''<section class="pro-proof" id="evidence"><div><p class="eyebrow">{tr('proof_label')}</p><h2>{tr('proof_title')}</h2><p>{tr('proof_body')}</p><a href="/docs/compatibility.html">{tr('proof_link')} →</a></div><div class="proof-numbers"><div><strong>{tests}</strong><span>{tr('proof_tests')}</span><small>{skipped} {tr('proof_skipped')}</small></div><div><strong>{len(lab['runs']):02d}</strong><span>{tr('proof_runs')}</span></div><div><strong>{len(lab['sources']):02d}</strong><span>{tr('proof_sources')}</span></div></div></section>'''
 capabilities='<section class="pro-section" id="capabilities"><div class="pro-section-heading"><p class="eyebrow">'+tr('cap_label')+'</p><h2>'+tr('cap_title')+'</h2></div><div class="capability-grid">'+''.join(f'<article><span class="pro-index">0{i+1}</span><h3>{tr("cap_"+key+"_title")}</h3><p>{tr("cap_"+key+"_body")}</p><a href="/docs/{"behaviours" if key!="replay" else "python-api"}.html">{esc(LOCALES[code]["nav"]["docs"])} ↗</a></article>' for i,key in enumerate(['count','dwell','replay']))+'</div></section>'
 flow='<section class="pro-flow"><div class="pro-section-heading"><p class="eyebrow">'+tr('flow_label')+'</p><h2>'+tr('flow_title')+'</h2></div><ol>'+''.join(f'<li><span>0{i+1}</span><div><h3>{tr("flow_"+key)}</h3><p>{tr("flow_"+key+"_body")}</p></div></li>' for i,key in enumerate(['detect','track','rule','evidence']))+'</ol><p class="pro-note">'+tr('flow_note')+'</p></section>'
 tabs=''.join(f'<button id="tab-{key}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="panel-{key}" tabindex="{0 if i==0 else -1}" data-command-tab="{key}">{tr("quick_"+key)}</button>' for i,key in enumerate(COPY_COMMANDS))
 panels=''.join(f'<div id="panel-{key}" role="tabpanel" aria-labelledby="tab-{key}" {"hidden" if i else ""}>{code_block(command,code)}</div>' for i,(key,command) in enumerate(COPY_COMMANDS.items()))
 quick=f'<section class="pro-quickstart" id="quickstart"><div><p class="eyebrow">{tr("quick_label")}</p><h2>{tr("quick_title")}</h2><p>{tr("quick_text")}</p><a href="{start}">{tr("quick_link")} →</a></div><div><div class="command-tabs" role="tablist" aria-label="{tr("quick_label")}">{tabs}</div>{panels}<p class="pro-note">{tr("quick_output")}</p></div></section>'
 hardware='<section class="pro-section"><div class="pro-section-heading"><p class="eyebrow">'+tr('hardware_label')+'</p><h2>'+tr('hardware_title')+'</h2><a href="/docs/compatibility.html">'+tr('hardware_link')+' ↗</a></div><div class="hardware-list">'+''.join(f'<article><div><span class="hardware-status {"verified" if key in ["intel","nvidia"] else "pending"}">{tr("hardware_verified" if key in ["intel","nvidia"] else "hardware_pending")}</span><h3>{tr("hardware_"+key)}</h3></div><p>{tr("hardware_"+key+"_body")}</p></article>' for key in ['intel','nvidia','amd','apple'])+'</div></section>'
 repositories=f'<section class="pro-repositories" id="repositories"><div class="pro-section-heading"><p class="eyebrow">{tr("repos_label")}</p><h2>{tr("repos_title")}</h2><p>{tr("repos_text")}</p></div><article class="own-source"><div><span class="repo-symbol" aria-hidden="true">&lt;/&gt;</span><h3>{tr("repos_own")}</h3><p>{tr("repos_own_body")}</p></div><a class="button" href="/downloads/behaviorkit-prototype-source.zip">{tr("repos_download")} ↗</a><a class="pro-text-link" href="https://github.com/arpanjot-coding/behaviorkit" target="_blank" rel="noopener" dir="ltr">GitHub ↗</a></article><div class="repo-grid">'+''.join(f'<a href="{url}" target="_blank" rel="noopener"><span class="repo-owner" dir="ltr">{owner}</span><h3 dir="auto">{name} ↗</h3><p>{tr(key)}</p><span>{tr("repos_upstream")}</span></a>' for name,owner,url,key in REPOS)+f'</div><a class="pro-text-link" href="/sources.html">{tr("repos_all")} →</a></section>'
 research=f'<section class="pro-research-callout"><span class="pro-index">R&amp;D</span><div><p class="eyebrow">{tr("research_label")}</p><h2>{tr("research_title")}</h2><p>{tr("research_text")}</p><a href="/research.html">{tr("research_link")} →</a></div></section>'
 faq='<section class="pro-faq"><h2>'+tr('faq_title')+'</h2><div>'+''.join(f'<details><summary>{tr("faq_q"+str(i))}</summary><p>{tr("faq_a"+str(i))}</p></details>' for i in range(1,6))+'</div></section>'
 bottom=f'<section class="pro-bottom"><h2>{tr("bottom_title")}</h2><p>{tr("bottom_text")}</p><div class="pro-actions"><a class="button" href="{start}">{tr("bottom_start")} →</a><a href="/sources.html">{tr("bottom_source")} ↗</a></div></section>'
 return clean(hero+proof+capabilities+flow+quick+hardware+repositories+research+faq+bottom)

def guide_body(code):
 t=LOCALES[code]['guide'];tr=lambda key:esc(t[key]);steps=[]
 commands=[COPY_COMMANDS['core'],'behaviorkit replay --observations runs/demo/observations.jsonl --config runs/demo/config.json --output runs/replayed',COPY_COMMANDS['cpu']+'\n\n# NVIDIA\n'+COPY_COMMANDS['cuda']+'\n\n# Apple Silicon\npython -m pip install -e ".[vision,apple]"','behaviorkit models','behaviorkit run --video sample.mp4 --model rtmdet-tiny --models-dir models --config configs/people.json --provider auto --sample-fps 5 --output runs/video','python scripts/validate_platform.py --output runs/platform']
 for i,command in enumerate(commands,1):
  if i==3:
   choices=[(LOCALES[code]['home']['quick_cpu'],COPY_COMMANDS['cpu']),(LOCALES[code]['home']['quick_cuda'],COPY_COMMANDS['cuda']),(LOCALES[code]['home']['hardware_apple'],'python -m pip install -e ".[vision,apple]"\nbehaviorkit doctor --provider cpu')]
   rendered=''.join(f'<details class="guide-runtime" {"open" if n==0 else ""}><summary>{esc(label)}</summary>{code_block(value,code)}</details>' for n,(label,value) in enumerate(choices))
  else:
   if i==6:command='behaviorkit benchmark models --models rtmdet-tiny --models-dir models --provider auto --threads 4 --output runs/benchmark.json\nbehaviorkit replay --observations runs/video/observations.jsonl --config runs/video/config.snapshot.json --output runs/replayed'
   rendered=code_block(command,code)
  steps.append(f'<section class="guide-step"><span class="pro-index">0{i}</span><div><h2>{tr(f"step{i}_title")}</h2><p>{tr(f"step{i}_body")}</p>{rendered}</div></section>')
 refs=[('commands','commands'),('contracts','model-contracts'),('semantics','behaviours'),('compatibility','compatibility'),('limits','troubleshooting')]
 return f'<article class="start-guide"><header><p class="eyebrow">BEHAVIORKIT / {esc(LOCALES[code]["nav"]["docs"]).upper()}</p><h1>{tr("title")}</h1><p class="pro-lead">{tr("intro")}</p><a class="button" href="/downloads/behaviorkit-prototype-source.zip">{tr("download")} ↗</a></header>'+''.join(steps)+f'<section class="guide-references"><h2>{tr("reference_title")}</h2><p>{tr("english_note")}</p>'+''.join(f'<a href="/docs/{slug}.html">{tr(key)} ↗</a>' for key,slug in refs)+'</section></article>'

def sources_body():
 repos=''.join(f'<article><span class="repo-owner">{esc(owner)}</span><h2>{esc(name)}</h2><p>{esc(LOCALES["en"]["home"][key])}</p><a href="{url}" target="_blank" rel="noopener">Open repository ↗</a><a href="/docs/model-contracts.html">Artifact contract and preparation ↗</a></article>' for name,owner,url,key in REPOS)
 return f'''<article class="source-page"><header class="page-intro"><p class="eyebrow">SOURCE / PROVENANCE / REPOSITORIES</p><h1>Inspect what you run.</h1><p class="pro-lead">Original code, runtime dependencies, model artifacts and demonstration media have separate provenance. Start with the source and keep the contracts visible.</p></header><section class="source-release"><span class="release-badge">BehaviorKit v0.3.0</span><h2>The current project source</h2><p>The source archive includes the Python library, tests, example observations, configuration, documentation and recorded evidence. The local wheel contains the installable library. Model weights and demo media are excluded.</p><div class="pro-actions"><a class="button" href="/downloads/behaviorkit-prototype-source.zip">Download source ZIP ↗</a><a href="/downloads/behaviorkit_prototype-0.3.0-py3-none-any.whl">Download Python wheel ↗</a><a href="https://github.com/arpanjot-coding/behaviorkit">GitHub repository ↗</a><a href="https://github.com/arpanjot-coding/behaviorkit/blob/main/ROADMAP.md">Roadmap and acceptance criteria ↗</a></div><p class="source-status">The library source, README, roadmap, issues and CI are published at arpanjot-coding/behaviorkit. PyPI publication is still pending. The upstream links below belong to their respective maintainers.</p></section><section><div class="pro-section-heading"><p class="eyebrow">UPSTREAM PROJECTS</p><h2>Models and the inference runtime.</h2></div><div class="source-repo-grid">{repos}</div></section><section class="source-license"><h2>Keep the license layers separate.</h2><p>Original BehaviorKit code is Apache-2.0. An upstream repository's code license does not automatically clear every checkpoint, training dataset, codec, driver or video. Preserve exact artifact hashes, publisher URLs, export/runtime versions and applicable notices.</p><p>RTMDet-Tiny, the selected D-FINE-N COCO checkpoint and RF-DETR-Nano are the current shortlist. Some related pretrained variants and model sizes have different terms. Review exact artifacts before redistribution.</p><a href="/docs/commercial-use.html">Read the commercial-use notes →</a></section><section><h2>Reproduce the evidence.</h2><div class="source-evidence-links"><a href="/downloads/reliability-v03.json">Hardware and software validation ↗</a><a href="/lab/report.json">All twelve video/model run summaries ↗</a><a href="/lab/sources.json">Video source manifest and hashes ↗</a><a href="/assets/research.json">Developer research and primary sources ↗</a></div></section></article>'''

def research_body():
 data=json.loads((ROOT/'website/research.json').read_text(encoding='utf-8'))
 priorities={'next':'Build next','after':'After reliability','later':'Explore later'}
 gaps=[]
 for i,g in enumerate(data['gaps'],1):
  links=[]
  for source in g['sources']:
   extra=' target="_blank" rel="noopener"' if source['url'].startswith('https:') else ''
   links.append(f'<li><a href="{esc(source["url"])}"{extra}>{esc(source["label"])} ↗</a><small>{esc(source["kind"])}</small></li>')
  sources=''.join(links)
  criteria=''.join(f'<li>{esc(s)}</li>' for s in g['acceptance'])
  search=esc(' '.join([g['title'],g['category'],g['pain'],g['opportunity']]).lower())
  gaps.append(f'<details class="research-gap" data-priority="{g["priority"]}" data-search="{search}" id="{g["id"]}"><summary><span class="gap-number">{i:02d}</span><span class="gap-heading"><small>{esc(g["category"])}</small><strong>{esc(g["title"])}</strong></span><span class="priority priority-{g["priority"]}">{priorities[g["priority"]]}</span></summary><div class="gap-detail"><p class="gap-pain">{esc(g["pain"])}</p><div class="gap-columns"><section><h3>What already exists</h3><p>{esc(g["existing"])}</p><h3>Where BehaviorKit could help</h3><p>{esc(g["opportunity"])}</p></section><section><h3>Current prototype</h3><p>{esc(g["prototype"])}</p><h3>Acceptance criteria to test</h3><ul>{criteria}</ul><p class="research-risk">{esc(g["risk"])}</p></section></div><section class="research-sources"><h3>Primary evidence</h3><ul>{sources}</ul></section></div></details>')
 phases=''.join(f'<article><span>{esc(p["phase"])}</span><div><h3>{esc(p["title"])}</h3><p>{esc(p["text"])}</p></div></article>' for p in data['sequence'])
 questions=''.join(f'<li>{esc(q)}</li>' for q in data['validation_questions']);non_goals=''.join(f'<li>{esc(q)}</li>' for q in data['non_goals'])
 return f'''<article class="research-page"><header class="page-intro"><p class="eyebrow">DEVELOPER RESEARCH / CHECKED 2 NOVEMBER 2026</p><h1>Find the gap between<br>vision and a dependable event.</h1><p class="pro-lead">{esc(data['thesis'])}</p><div class="research-method"><strong>Method and limits</strong><p>{esc(data['method'])}</p></div></header><section class="research-position"><p class="eyebrow">THE PRODUCT DIRECTION TO TEST</p><h2>Make existing tools work together with explicit evidence.</h2><div class="position-grid"><div><h3>Models and tracking</h3><p>Use established detectors, Supervision and current tracker adapters. Counting zones or another generic detector wrapper alone is a weak differentiation.</p><a href="https://github.com/roboflow/trackers">Trackers repository ↗</a></div><div><h3>Streaming and operations</h3><p>Integrate mature ingest, reconnection and batching backends. Add a portable source-health, clock and evidence-freshness contract rather than rebuilding a media stack.</p><a href="https://docs.nvidia.com/deepstream/text/DS_plugin_gst-nvdsanalytics">DeepStream analytics ↗</a></div><div><h3>Data and evaluation</h3><p>Connect CVAT, FiftyOne and TrackEval to behaviour-level failures. Do not create another general annotation platform when the useful gap is a reproducible event regression.</p><a href="https://docs.voxel51.com/user_guide/evaluation/detections.html">Temporal evaluation ↗</a></div></div></section><section class="research-roadmap"><div class="pro-section-heading"><p class="eyebrow">PROPOSED SEQUENCE, NOT A SHIPPING PROMISE</p><h2>Qualify. Measure. Stabilize. Then expand.</h2></div>{phases}</section><section class="gap-explorer"><div class="pro-section-heading"><p class="eyebrow">{len(gaps)} CONCRETE OPPORTUNITIES</p><h2>Inspect the problem, existing solution and acceptance test.</h2></div><div class="research-controls"><div class="research-filters" role="group" aria-label="Filter by proposed priority"><button data-gap-filter="all" aria-pressed="true">All</button><button data-gap-filter="next" aria-pressed="false">Build next</button><button data-gap-filter="after" aria-pressed="false">After reliability</button><button data-gap-filter="later" aria-pressed="false">Explore later</button></div><label><span class="sr-only">Search developer gaps</span><input id="gap-search" type="search" placeholder="Search timing, tracking, deployment…"></label></div><p id="gap-count" role="status">{len(gaps)} opportunities</p><div id="gap-results">{''.join(gaps)}</div><p id="gap-empty" hidden>No matching opportunities. Try another term or priority.</p></section><section class="research-interviews"><div><p class="eyebrow">THE NEXT VALIDATION STEP</p><h2>Use developer interviews and deployment pilots.</h2><p>Public issue reports are technical signals. Commercial demand and the most valuable workflow still need direct validation with developers and their actual camera constraints.</p><ol>{questions}</ol></div><div><p class="eyebrow">KEEP THE SCOPE DISCIPLINED</p><h2>What this research does not justify.</h2><ul>{non_goals}</ul><a href="/assets/research.json">Download the full research dataset ↗</a><a href="/docs/compatibility.html">Inspect current prototype evidence ↗</a></div></section></article>'''
